-- Dish prep tasks (26).
insert into dish_prep_tasks (id, dish_id, task_name, required_before_minutes, description)
select md5('prep_task:' || v.dish || '|' || v.task)::uuid, d.id, v.task, v.mins, v.descr
from (values
  ('Rajma Masala', 'Soak kidney beans', 480, 'Soak rajma in water for at least 8 hours (overnight).'),
  ('Chole Masala', 'Soak chickpeas', 480, 'Soak kabuli chana overnight (8h).'),
  ('Dal Makhani', 'Soak dal and beans', 480, 'Soak whole urad and rajma overnight (8h).'),
  ('Kala Chana Masala', 'Soak black chickpeas', 480, 'Soak kala chana overnight (8h).'),
  ('Butter Naan', 'Rest the dough', 90, 'Let the naan dough proof for ~90 minutes.'),
  ('Bhature', 'Rest the dough', 120, 'Ferment/rest the bhatura dough for ~2 hours.'),
  ('Vegetable Biryani', 'Marinate the vegetables', 60, 'Marinate veg in spiced yogurt for an hour.'),
  ('Idli', 'Soak and ferment batter', 720, 'Soak rice + dal, grind, and ferment 8-12h.'),
  ('Masala Dosa', 'Ferment dosa batter', 720, 'Ferment the ground batter overnight (8-12h).'),
  ('Plain Dosa', 'Ferment dosa batter', 720, 'Ferment the ground batter overnight (8-12h).'),
  ('Medu Vada', 'Soak urad dal', 240, 'Soak urad dal for ~4 hours before grinding.'),
  ('Uttapam', 'Ferment batter', 720, 'Ferment dosa-style batter overnight.'),
  ('Dhokla', 'Rest the batter', 30, 'Let the besan batter rest ~30 minutes before steaming.'),
  ('Sabudana Khichdi', 'Soak sago', 480, 'Soak sabudana for 6-8 hours until soft.'),
  ('Paneer Tikka', 'Marinate the paneer', 120, 'Marinate paneer in spiced yogurt for ~2 hours.'),
  ('Butter Chicken', 'Marinate the chicken', 240, 'Marinate chicken in yogurt + spices ~4 hours.'),
  ('Chicken Biryani', 'Marinate the chicken', 120, 'Marinate chicken in spiced yogurt ~2 hours.'),
  ('Tandoori Chicken', 'Marinate the chicken', 240, 'Marinate chicken in yogurt + tandoori masala ~4 hours.'),
  ('Chicken Tikka', 'Marinate the chicken', 180, 'Marinate chicken ~3 hours for tikka.'),
  ('Mutton Rogan Josh', 'Marinate the mutton', 120, 'Marinate mutton in yogurt + spices ~2 hours.'),
  ('Chicken 65', 'Marinate the chicken', 60, 'Marinate chicken ~1 hour before frying.'),
  ('Fish Fry', 'Marinate the fish', 60, 'Marinate fish in lemon + spices ~1 hour.'),
  ('Margherita Pizza', 'Prove the dough', 90, 'Let the pizza dough rise ~90 minutes.'),
  ('Rajma Quinoa Bowl', 'Soak kidney beans', 480, 'Soak rajma overnight (8h).'),
  ('Chickpea Salad', 'Soak chickpeas', 480, 'Soak chickpeas overnight, then boil.'),
  ('Hummus', 'Soak chickpeas', 480, 'Soak chickpeas overnight, then boil until soft.')
) as v(dish, task, mins, descr)
join dishes d on d.name = v.dish
on conflict do nothing;

